function thousandSeparator(n) {
  // Peel off three digits at a time with arithmetic, padding inner groups with zeros.
  const groups = [];
  let rest = n;
  while (rest >= 1000) {
    groups.unshift(String(rest % 1000).padStart(3, '0'));
    rest = Math.floor(rest / 1000);
  }
  groups.unshift(String(rest));
  return groups.join('.');
}

